function startGame(){
  scene.children.filter(c=>c.userData&&c.userData.fire).forEach(c=>scene.remove(c));
  const fireGroup = new THREE.Group(); fireGroup.userData.fire = true;
  const count = 80; const geo = new THREE.SphereGeometry(0.08, 8, 8);
  for(let i=0; i<count; i++){
    const mat = new THREE.MeshBasicMaterial({ color: new THREE.Color().setHSL(0.08 - Math.random()*0.05, 1, 0.6), transparent: true, opacity: 0.85 });
    const p = new THREE.Mesh(geo, mat);
    p.position.set((Math.random()-0.5)*0.6, Math.random()*0.2, (Math.random()-0.5)*0.6);
    p.userData = { vy: 0.015 + Math.random()*0.02, life: Math.random() };
    fireGroup.add(p);
  }
  scene.add(fireGroup);
  const light = new THREE.PointLight(0xff6600, 2, 5); light.position.set(0, 0.5, 0); light.userData.fire = true; scene.add(light);
  const animateFire = () => {
    fireGroup.children.forEach(p => {
      p.position.y += p.userData.vy; p.userData.life += 0.02;
      p.material.opacity = 0.85 * (1 - p.userData.life*0.3);
      p.scale.setScalar(1 + p.userData.life*0.5);
      if(p.position.y > 2.5){ p.position.y = 0; p.userData.life = 0; }
    });
    light.intensity = 1.5 + Math.sin(Date.now()*0.01)*0.5;
    requestAnimationFrame(animateFire);
  };
  animateFire();
}
